(6280167, 928111, 108069, '<td valign="top">Great story here. B&amp;W is perfect for this. Those skates look old. Great photo.</td>', 'Great story here. B&W is perfect for this. Those skates look old. Great photo.', '2011-01-11 18:09:13.000000', NULL, 1),
(6280172, 928221, 108069, '<td valign="top">Wow, this is great. The fact that he''s standing right in the path of the sun is great, and helps me get over the fact that the sun is near dead center in the frame. But the scene is amazing. Chaotic and mysterious. Awesome photo.</td>', 'Wow, this is great. The fact that he''s standing right in the path of the sun is great, and helps me get over the fact that the sun is near dead center in the frame. But the scene is amazing. Chaotic and mysterious. Awesome photo.', '2011-01-11 18:11:45.000000', NULL, 1),
